import {formatValidationError, ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry schema compilation', () => {
  it('passes valid input and undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        inputs.push(input);
        return 'sunny';
      }
    );

    const input = {location: 'Paris', requestId: 'opaque'};
    await registry.execute('get_weather', input);

    expect(inputs).toEqual([input]);
  });

  it('compiles a static schema once across repeated executions', async () => {
    let schemaReads = 0;
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      get inputSchema() {
        schemaReads += 1;
        return inputSchema;
      },
    } as ToolDefinition;
    const registry = new ToolRegistry();

    registry.register(definition, async () => 'sunny');
    for (let call = 0; call < 10; call += 1) {
      await registry.execute('get_weather', {location: 'Paris'});
    }

    expect(schemaReads).toBe(1);
  });

  it('reports a wrong-typed property by path without the offending value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup', {identifier: 123456789});

    expect({
      executorCalls,
      result: response.result,
    }).toEqual({
      executorCalls: 0,
      result: 'Invalid input: /identifier must be string',
    });
  });

  it('reports a nested wrong-typed property by its full instance path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested record',
        inputSchema: {
          type: 'object',
          properties: {
            lookup: {
              type: 'object',
              properties: {identifier: {type: 'string'}},
            },
          },
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {lookup: {identifier: 123456789}});

    expect(response.result).toBe('Invalid input: /lookup/identifier must be string');
  });

  it('recovers a property path when the validator omits instancePath', () => {
    expect(
      formatValidationError({
        schemaPath: '#/properties/identifier/type',
        params: {type: 'string'},
        message: 'must be string',
      })
    ).toBe('/identifier must be string');
  });

  it('normalizes validator type wording to the public must form', () => {
    expect(
      formatValidationError({
        instancePath: '/identifier',
        message: 'should be string',
      })
    ).toBe('/identifier must be string');
  });
});
